#!/usr/bin/env bash
set -uo pipefail
REPO_DIR="${CARE_ASD_REPO_DIR:-$HOME/Dung_TDTU/CARE_ASD}"; cd "$REPO_DIR"; RUN_FILE="outputs/fp_naa/latest_lomo_run_id.txt"
if [ ! -f "$RUN_FILE" ]; then printf 'No FP-NAA LOMO run has been started.\n'; exit 0; fi
RUN_ID="$(cat "$RUN_FILE")"; JOB_DIR="outputs/fp_naa/$RUN_ID"; REPORT_DIR="reports/fp_naa/$RUN_ID/lomo"; printf 'RUN_ID=%s\n\nSTATE:\n' "$RUN_ID"; [ -f "$JOB_DIR/state.env" ] && cat "$JOB_DIR/state.env" || printf 'state file not created yet\n'; printf '\nPROCESS:\n'; pgrep -af '[r]un_fp_naa_lomo.sh|care-asd fp-naa lomo-dev' || printf 'no matching process\n'; printf '\nLOMO PROGRESS:\n'; [ -f "$REPORT_DIR/progress.env" ] && cat "$REPORT_DIR/progress.env" || printf 'LOMO progress not created yet\n'; printf '\nRESOURCE SNAPSHOT:\n'; ps -eo pid,etime,stat,pcpu,pmem,args | grep -E '[c]are-asd fp-naa lomo-dev|[r]un_fp_naa_lomo' || true; printf '\nGPU:\n'; nvidia-smi --query-compute-apps=pid,process_name,used_memory --format=csv,noheader 2>/dev/null || true; printf '\nLOG TAIL:\n'; tail -n 30 "$JOB_DIR/fp_naa_lomo.log" 2>/dev/null || true; if [ -f "$REPORT_DIR/lomo_fold_means.csv" ]; then printf '\nFOLD MEANS:\n'; column -s, -t < "$REPORT_DIR/lomo_fold_means.csv"; fi; if [ -f "$REPORT_DIR/gate.json" ]; then printf '\nGATE:\n'; cat "$REPORT_DIR/gate.json"; fi
